// Mapování kódů období na české textové popisky
window.MAPA_OBDOBI = {
    "do18": "Do konce 18. st.",
    "19": "19. století",
    "cz20": "ČR 20. a 21. st.",
    "svet20": "Svět 20. a 21. st."
};

// Bezpečné získání dat z OMEGA_CONFIG (injektovaného přes data-spspb.js)
window.getOmegaConfig = function() {
    return window.OMEGA_CONFIG || {};
};

window.getKnihyDb = function() {
    return (window.OMEGA_CONFIG && window.OMEGA_CONFIG.KNIHY_DB) ? window.OMEGA_CONFIG.KNIHY_DB : [];
};

window.getRequirements = function() {
    return (window.OMEGA_CONFIG && window.OMEGA_CONFIG.REQUIREMENTS) 
        ? window.OMEGA_CONFIG.REQUIREMENTS 
        : { do18: 2, "19": 3, svet20: 4, cz20: 5, lyrika: 2, epika: 2, drama: 2 };
};

// Zpětná kompatibilita pro přímé proměnné
window.KNIHY_DB = window.getKnihyDb();
window.REQUIREMENTS = window.getRequirements();

