// Konfigurace pro Cloudflare Worker API
window.OMEGA_ADMIN_CONFIG = {
    WORKER_URL: "https://spspb-mat-cet.tresnakkarel77.workers.dev"
};

// Deterministický výpočet kontrolního hashe databáze děl (pro detekci mutací a URL payloadů)
window.generateDbHash = function(db) {
    if (!db || !Array.isArray(db)) return "empty";
    const str = db.map(k => k.id + k.dilo).join('|');
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        hash = ((hash << 5) - hash) + str.charCodeAt(i);
        hash |= 0; 
    }
    return hash.toString(36);
};

window.DB_VERSION = window.generateDbHash(window.KNIHY_DB);

// ZERO-TRUST FETCH INTERCEPTOR (Automatická injekce JWT Tokenů a ošetření vypršení)
(function() {
    const originalFetch = window.fetch;
    window.fetch = async function(resource, config) {
        if (typeof resource === 'string' && resource.startsWith(window.OMEGA_ADMIN_CONFIG.WORKER_URL)) {
            config = config || {};
            config.headers = config.headers || {};
            const token = sessionStorage.getItem('omega_session_token');
            if (token) config.headers['Authorization'] = `Bearer ${token}`;
        }
        const response = await originalFetch(resource, config);
        
        // Pokud Token vypršel (401 Unauthorized) a nejsme na endpointu pro login
        if (response.status === 401 && typeof resource === 'string' && !resource.includes('/login')) {
            sessionStorage.removeItem('omega_session_token');
            sessionStorage.removeItem('omega_active_user');

            // Detekce, zda šlo o ukončení relace kvůli souběžnému přihlášení na jiném zařízení
            try {
                const clone = response.clone();
                const errData = await clone.json();
                if (errData.error === "SESSION_TERMINATED") {
                    sessionStorage.setItem('omega_session_terminated', 'true');
                    window.location.reload();
                    return response;
                }
            } catch (e) {}

            sessionStorage.setItem('omega_security_breach', 'true');
            window.location.reload();
        }
        return response;
    };
})();

// Export do jmenného prostoru Omega
window.Omega.config = {
    VERSION: window.OMEGA_VERSION,
    STORAGE_KEY: window.STORAGE_KEY,
    MAPA_OBDOBI: window.MAPA_OBDOBI,
    ADMIN_CONFIG: window.OMEGA_ADMIN_CONFIG,
    generateDbHash: window.generateDbHash
};
